```python
def solve(n, roads):
    import heapq

    # Create adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Check if the graph is connected using BFS
    def is_connected(start):
        visited = [False] * n
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            for neighbor, _ in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return all(visited)

    # If the graph is not connected, return -1
    if not is_connected(0):
        return -1

    # Kruskal's algorithm to find MST
    edges = []
    for u, v, w in roads:
        edges.append((w, u, v))

    # Sort edges by weight
    edges.sort()

    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False
        parent[root_v] = root_u
        return True

    total_cost = 0
    count = 0
    for w, u, v in edges:
        if union(u, v):
            total_cost += w
            count += 1
            if count == n - 1:
                break

    return total_cost
